-- Top Customers by Revenue
With TopCustRev AS (
SELECT 
	CustomerID,
	COUNT (DISTINCT Invoice) AS Orders,
	SUM(Revenue) AS Revenue
FROM OnlineRetail..OnlineRetail
GROUP BY CustomerID
)
SELECT
	CustomerID,
	Orders,
	ROUND(Revenue, 2) AS Revenue,
	ROUND(Revenue * 1.0/Orders,2) AS Average_Order_Value
FROM TopCustRev	
WHERE CustomerID is not null
ORDER BY Revenue DESC

-- Revenue Concentration
-- How much revenue is generated by the top 10% of customers, the next 10% and so on...
WITH CustRev AS (
SELECT
	CustomerID,
	SUM(Revenue) AS Revenue
From OnlineRetail..OnlineRetail
GROUP BY CustomerID
)
,RankCus AS(
SELECT 
	CustomerID,
	Revenue,
	NTILE(10) OVER (ORDER BY Revenue DESC) AS Revenue_Decline
FROM CustRev
)
SELECT
	Revenue_Decline,
	COUNT (*) AS Customers,
	ROUND(SUM(Revenue),2) AS Decline_Revenue
FROM RankCus
GROUP BY Revenue_Decline
ORDER BY Revenue_Decline
		
-- Customer Repeat Rate
WITH CustOrders AS(
SELECT
	CustomerID,
	COUNT(DISTINCT Invoice) AS Orders
FROM OnlineRetail..OnlineRetail
GROUP BY CustomerID
)
SELECT 
	COUNT (*) AS Total_Customer,
	SUM(CASE WHEN Orders > 1 THEN 1 ELSE 0 END) AS RepeatCustomers,
	ROUND(100 * SUM(CASE WHEN Orders > 1 THEN 1 ELSE 0 END) / COUNT (*), 2) AS Customer_Repeat_Rate
FROM CustOrders
